int def scoreHealth(int:expired, int:total) {
    if (expired == 0) {
        return 20;
    } else if (expired * 10 < total) {
        return 12;
    } else if (expired * 10 < total * 3) {
        return 6;
    } else {
        return 0;
    }
}


int def scoreTraining(int:rate) {
    if (rate >= 100) {
        return 15;
    } else if (rate >= 80) {
        return 12;
    } else if (rate >= 60) {
        return 8;
    } else {
        return 2;
    }
}


int def scoreOfficer(boolean:hasOfficer) {
    if (hasOfficer) {
        return 10;
    } else {
        return 0;
    }
}


int def scoreDefects(int:defectCount) {
    if (defectCount == 0) {
        return 15;
    } else if (defectCount <= 2) {
        return 10;
    } else if (defectCount <= 5) {
        return 5;
    } else {
        return 0;
    }
}


int def scoreRectification(boolean:completed) {
    if (completed) {
        return 10;
    } else {
        return 0;
    }
}


int def scoreComplaints(int:complaintCount) {
    if (complaintCount == 0) {
        return 10;
    } else if (complaintCount <= 3) {
        return 6;
    } else if (complaintCount <= 10) {
        return 2;
    } else {
        return 0;
    }
}


int def scoreEnvironment(str:rating) {
    if (rating == "A") {
        return 10;
    } else if (rating == "B") {
        return 6;
    } else {
        return 0;
    }
}


int def scoreInsurance(boolean:hasInsurance) {
    if (hasInsurance) {
        return 10;
    } else {
        return 5;
    }
}


str def reviewLevel(int:totalScore) {
    if (totalScore >= 85) {
        return "PASS";
    } else if (totalScore >= 70) {
        return "CONDITIONAL";
    } else {
        return "FAIL";
    }
}
